-- T011 — the credential pass of Phase 1 (specs/002-identity/data-model.md §1, §2, §3, §5; ERD §2,
-- §3, §4, §15; ADR 0017 D5, ADR 0019 D1). Generated by `prisma migrate diff
-- --from-config-datasource --to-schema prisma/schema --script` against a database holding every
-- migration before it, then extended by hand below the marker.
--
-- What it lands: `teacher_credentials`, one ijazah PDF per subject with its transcription;
-- `isnad_entries` re-keyed under the credential (`credential_id`, `names text[]`,
-- `created_by_admin_id`; the teacher, subject, transmitter name and verification columns dropped —
-- the table held no row in any environment, so the columns are dropped rather than deprecated, and
-- `isnad_verification_status` stays declared); the `teacher_profiles` application columns (§3), the
-- payout reference hash and rejection reason, and `approved_shown_at`; `revoked` on
-- `teacher_verification_status`; `verification_requests.document_id` and `document_type`, the latter
-- sharing `identity_document_type` with the profile; the uniques of rules 27 and 28.
-- CreateEnum
CREATE TYPE "teacher_application_status" AS ENUM ('in_review', 'needs_document', 'rejected', 'banned', 'approved');

-- CreateEnum
CREATE TYPE "identity_document_type" AS ENUM ('national_id', 'passport');

-- CreateEnum
CREATE TYPE "teacher_credential_status" AS ENUM ('pending', 'needs_document', 'approved', 'rejected');

-- AlterEnum
ALTER TYPE "teacher_verification_status" ADD VALUE 'revoked';

