-- AlterTable
ALTER TABLE "verification_requests" ADD COLUMN     "document_id" UUID,
ADD COLUMN     "document_type" "identity_document_type";

-- CreateTable
CREATE TABLE "teacher_credentials" (
    "id" UUID NOT NULL DEFAULT uuidv7(),
    "teacher_user_id" UUID NOT NULL,
    "subject_id" UUID NOT NULL,
    "document_id" UUID NOT NULL,
    "holder_name" TEXT,
    "riwaya" TEXT,
    "tariq" TEXT,
    "status" "teacher_credential_status" NOT NULL,
    "review_reason" TEXT,
    "reviewed_by_admin_id" UUID,
    "reviewed_at" TIMESTAMPTZ(6),
    "submitted_with_application" BOOLEAN NOT NULL,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(6) NOT NULL,

    CONSTRAINT "teacher_credentials_pkey" PRIMARY KEY ("id")
);

