-- Hand-written: what the schema language cannot say (data-model.md §5, ERD §15).

-- Rule 23: one approved credential per teacher and subject; a rejected one stays as history and a
-- new upload for the same subject is a new row.
CREATE UNIQUE INDEX "teacher_credentials_teacher_user_id_subject_id_approved_key"
    ON "teacher_credentials" ("teacher_user_id", "subject_id") WHERE "status" = 'approved';

-- A generation holds one or more names (ADR 0004 D3): never null, never empty. The schema language
-- declares a list as a nullable array, so the rule is stated here.
ALTER TABLE "isnad_entries" ADD CONSTRAINT "isnad_entries_names_check"
    CHECK ("names" IS NOT NULL AND cardinality("names") > 0);
